{
  "title": "Đà Lạt một góc, trọn một ngày",
  "summary": "Ngày thứ tư cứ thong thả trong lòng Đà Lạt, từ bữa trưa ấm bụng đến cà phê đêm, không cần rời xa khu trung tâm.",
  "stops": [
    {
      "poi_id": "p157",
      "kind": "meal",
      "must_do_id": null,
      "note": "Bữa trưa ngồi xuống cho đàng hoàng, nem nướng thơm lừng đúng kiểu Đà Lạt, ăn chậm cho đã."
    },
    {
      "poi_id": "p14",
      "kind": "activity",
      "must_do_id": null,
      "note": "Tản bộ quanh quảng trường, nhìn nhịp sống phố núi trôi nhẹ, chẳng cần đi đâu xa."
    },
    {
      "poi_id": "p3",
      "kind": "activity",
      "must_do_id": null,
      "note": "Ghé nhà thờ Con Gà buổi sáng muộn, ngắm kiến trúc xưa và hít thở không khí yên ả."
    },
    {
      "poi_id": "p22",
      "kind": "meal",
      "must_do_id": null,
      "note": "Tối đến ngồi xuống Góc Hà Thành, món Hà Nội giữa Đà Lạt, ấm áp và chậm rãi."
    },
    {
      "poi_id": "p49",
      "kind": "activity",
      "must_do_id": null,
      "note": "Sau bữa tối, ghé Mây Lang Thang nhâm nhi cà phê, nghe đêm Đà Lạt kể chuyện."
    }
  ]
}
